import{_ as t,c as s,o as n,a0 as a}from"./chunks/framework.BAYjNulo.js";const m=JSON.parse('{"title":"Users and Identities","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/users.md","filePath":"documentation/users.md"}'),i={name:"documentation/users.md"};function o(r,e,c,d,u,h){return n(),s("div",null,e[0]||(e[0]=[a('<h1 id="users-and-identities" tabindex="-1">Users and Identities <a class="header-anchor" href="#users-and-identities" aria-label="Permalink to &quot;Users and Identities&quot;">​</a></h1><p>In GeoShop, user management is based on standard Django user accounts, which include basic information and permissions. It is essential to check the <em><strong>Active</strong></em> checkbox; otherwise, the user will be unable to log in.</p><p>Each user must have an <em><strong>Identity</strong></em>, which is automatically created upon registration. Identities store additional information that is not directly related to authentication and permissions, such as address, date of birth, and more.</p><p>While you cannot create an user without an associated Identity, you can create an Identity independently without linking it to a user.</p><p>Identities, whether associated with users or not, can be linked to Metadata as contact persons. To do this, you must obtain consent from the individual. Once you have consent, you can check the <em><strong>is_public</strong></em> checkbox on the Identity, allowing it to be used as a contact person.</p><h2 id="subscription" tabindex="-1">Subscription <a class="header-anchor" href="#subscription" aria-label="Permalink to &quot;Subscription&quot;">​</a></h2><p>The <em><strong>Subscribed</strong></em> checkbox is meant to manage subscriptions. A subscribed user will be able to order for free every product marked as <em><strong>free_when_subscribed</strong></em>.</p>',7)]))}const p=t(i,[["render",o]]);export{m as __pageData,p as default};
